div.div:
enter / {
obj.maxAlertness();
obj.swellSpeed = 30;
obj.useTile("mad");
obj.playHuntSound();
obj.stallTracker.reset();
}
do / {
obj.doHuntPlayer();
obj.stallTracker.update();
}
exit / {
obj.resetTile();
}

enter / {
timer.set(rand(0.5,2);
obj.useTile("groggy");
}
do / accumulateWake();
exit / {
obj.resetTile();
}

enter / {
timer.set(rand(0.2,2);
obj.useTile("startled");
}
exit / {
obj.resetTile();
obj.playMutterSound();
}
